// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        vm.assume(caller != c.owner());
        address originalOwner = c.owner();
        vm.prank(caller);
        try c.setOwner(caller) { } catch { }
        bool unchanged = (c.owner() == originalOwner);
        assertTrue(unchanged);
    }
}
